<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/sales_step15.php';if(empty($_SESSION['crm_customer_csrf']))$_SESSION['crm_customer_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['crm_customer_csrf'];$error=null;$success=null;$customers=[];$members=[];$edit=null;
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$id=sales_step15_save_customer($pdo,(int)($_POST['customer_id']??0),$_POST);$success='Customer #'.$id.' saved.';}$customers=sales_step15_customers($pdo,$orgId);$members=product_step12_members($pdo,$orgId);$editId=(int)($_GET['edit']??0);if($editId>0)$edit=sales_step15_customer($pdo,$orgId,$editId);}catch(Throwable $e){$error=$e->getMessage();}
function cc_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function cc_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Customer Center - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • Customer CRM</small></span></a><div class="os-top-actions"><a class="os-btn" href="sales_fulfillment.php">Fulfillment</a><a class="os-btn" href="crm_followups.php">Follow-ups</a><a class="os-btn primary" href="index.php">Dashboard</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Customers & Sales</div><nav class="os-nav"><a class="active" href="customer_center.php"><i class="dot"></i>Customers</a><a href="sales_fulfillment.php"><i class="dot"></i>Fulfillment</a><a href="sales_invoice.php"><i class="dot"></i>Invoices</a><a href="sales_delivery.php"><i class="dot"></i>Delivery</a><a href="sales_returns.php"><i class="dot"></i>Returns</a><a href="sales_refunds.php"><i class="dot"></i>Refunds</a><a href="sales_receivables.php"><i class="dot"></i>Receivables</a><a href="crm_followups.php"><i class="dot"></i>Follow-ups</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 15A • CUSTOMER MASTER</div><h1>Keep customers separate from members, but link them explicitly when verified.</h1><p>Name or mobile never auto-merges identities. A Product Sale may remain snapshot-only until you choose the correct Customer Master record.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'CUSTOMER CRM LIVE':'Review required' ?></span><span class="os-chip"><?= count($customers) ?> customers</span><span class="os-chip">Explicit member link</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Customer diagnostic:</strong> <?= cc_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Saved:</strong> <?= cc_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-5"><h2><?= $edit?'Edit Customer':'Add Customer' ?></h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= cc_h($csrf) ?>"><input type="hidden" name="customer_id" value="<?= (int)($edit['id']??0) ?>"><label>Customer Name<input name="customer_name" value="<?= cc_h($edit['customer_name']??'') ?>" required></label><label>Mobile<input name="mobile" value="<?= cc_h($edit['mobile']??'') ?>"></label><label>Email<input type="email" name="email" value="<?= cc_h($edit['email']??'') ?>"></label><label>Customer Type<select name="customer_type"><?php foreach(['retail'=>'Retail','preferred'=>'Preferred Customer','associate'=>'Associate','member'=>'Member Customer','other'=>'Other'] as $k=>$v):?><option value="<?= cc_h($k) ?>" <?= ($edit['customer_type']??'retail')===$k?'selected':'' ?>><?= cc_h($v) ?></option><?php endforeach;?></select></label><label>Verified Member Link (optional)<select name="member_id"><option value="">No member link</option><?php foreach($members as $m):?><option value="<?= (int)$m['id'] ?>" <?= (int)($edit['member_id']??0)===(int)$m['id']?'selected':'' ?>><?= cc_h($m['full_name'].' • #'.$m['id'].($m['mobile']?' • '.$m['mobile']:'')) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="active" <?= ($edit['status']??'active')==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= ($edit['status']??'')==='inactive'?'selected':'' ?>>Inactive</option></select></label><label>Notes<textarea name="notes" rows="3"><?= cc_h($edit['notes']??'') ?></textarea></label><button><?= $edit?'Update Customer':'Create Customer' ?> →</button></form></article><article class="os-card pp-span-7"><div class="os-title-row"><div><h2>Customer Master</h2><p>Sales and balances appear after explicit sale linkage.</p></div></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Customer</th><th>Contact</th><th>Type</th><th>Member</th><th>Sales</th><th>Receivable</th><th>Credit Due</th><th></th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td><a href="customer_detail.php?id=<?= (int)$c['id'] ?>"><b><?= cc_h($c['customer_name']) ?></b></a><small><?= cc_h($c['customer_code'].' • '.strtoupper($c['status'])) ?></small></td><td><?= cc_h($c['mobile']?:'—') ?><small><?= cc_h($c['email']?:'') ?></small></td><td><?= cc_h(ucwords(str_replace('_',' ',$c['customer_type']))) ?></td><td><?= cc_h($c['member_name']?:'—') ?></td><td><?= (int)$c['sales_count'] ?><small><?= cc_m($c['original_charge']) ?></small></td><td><b><?= cc_m($c['receivable']) ?></b></td><td><?= cc_m($c['credit_due']) ?></td><td><a href="?edit=<?= (int)$c['id'] ?>">Edit</a> · <a href="customer_detail.php?id=<?= (int)$c['id'] ?>">360°</a></td></tr><?php endforeach;?><?php if(!$customers):?><tr><td colspan="8">No Customer Master records yet. This is valid; existing sales remain snapshot-only until explicitly linked.</td></tr><?php endif;?></tbody></table></div></article></section><?php endif;?><div class="os-footer-note"><strong>Identity rule:</strong> duplicate/shared names or mobile numbers are never merged automatically.</div></main></div></body></html>